  isInRange,
  isNotEmpty,
  isOneOf,
  isUrl,
  matches,
  useForm,
} from '@mantine/form';

function Demo() {
  const form = useForm({
    mode: 'uncontrolled',
    initialValues: {
      name: '',
      job: '',
      email: '',
      favoriteColor: '',
